-- MEDILINK TN - A executer dans un NOUVEAU projet Supabase
create extension if not exists pgcrypto;
create type public.user_role as enum ('patient','doctor','admin');
create type public.verification_status as enum ('pending','verified','rejected');
create type public.permission_status as enum ('active','revoked','expired');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,role public.user_role not null default 'patient',created_at timestamptz not null default now());
create table public.patient_profiles(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references auth.users(id) on delete cascade,patient_code text unique not null default ('MLT-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6))),full_name text not null default '',birth_date date,blood_type text check(blood_type is null or blood_type in ('A+','A-','B+','B-','AB+','AB-','O+','O-')),phone text,allergies text,medical_history text,current_treatments text,emergency_name text,emergency_phone text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.doctor_profiles(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references auth.users(id) on delete cascade,display_name text not null default '',specialty text not null default '',professional_number text,phone text,city text,address text,latitude double precision,longitude double precision,verification_status public.verification_status not null default 'pending',created_at timestamptz default now());
create table public.patient_doctor_permissions(id uuid primary key default gen_random_uuid(),patient_id uuid not null references public.patient_profiles(id) on delete cascade,doctor_id uuid not null references public.doctor_profiles(id) on delete cascade,status public.permission_status not null default 'active',expires_at timestamptz,revoked_at timestamptz,created_at timestamptz default now(),unique(patient_id,doctor_id));
create table public.medical_documents(id uuid primary key default gen_random_uuid(),patient_id uuid not null references public.patient_profiles(id) on delete cascade,document_type text not null,file_name text not null,storage_path text not null,created_at timestamptz default now());
create table public.consultations(id uuid primary key default gen_random_uuid(),patient_id uuid not null references public.patient_profiles(id) on delete cascade,doctor_id uuid not null references public.doctor_profiles(id) on delete restrict,reason text,clinical_notes text,care_plan text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_user_id uuid,action text not null,entity_type text,entity_id uuid,created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,role) values(new.id,case when new.raw_user_meta_data->>'role'='doctor' then 'doctor'::public.user_role else 'patient'::public.user_role end); if coalesce(new.raw_user_meta_data->>'role','patient')='patient' then insert into public.patient_profiles(user_id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); end if; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.has_patient_access(pid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from patient_doctor_permissions p join doctor_profiles d on d.id=p.doctor_id where p.patient_id=pid and d.user_id=auth.uid() and d.verification_status='verified' and p.status='active' and (p.expires_at is null or p.expires_at>now()))$$;
create or replace function public.doctor_get_patient_by_code(requested_code text) returns table(patient_id uuid,patient_code text,full_name text,birth_date date,blood_type text,allergies text,medical_history text,current_treatments text) language sql security definer set search_path=public as $$select p.id,p.patient_code,p.full_name,p.birth_date,p.blood_type,p.allergies,p.medical_history,p.current_treatments from patient_profiles p where upper(p.patient_code)=upper(requested_code) and public.has_patient_access(p.id)$$;
revoke all on function public.doctor_get_patient_by_code(text) from public;grant execute on function public.doctor_get_patient_by_code(text) to authenticated;
alter table profiles enable row level security;alter table patient_profiles enable row level security;alter table doctor_profiles enable row level security;alter table patient_doctor_permissions enable row level security;alter table medical_documents enable row level security;alter table consultations enable row level security;alter table audit_logs enable row level security;
create policy "own profile" on profiles for select using(id=auth.uid());
create policy "patient own row" on patient_profiles for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "verified doctors public directory" on doctor_profiles for select using(verification_status='verified' or user_id=auth.uid());
create policy "doctor updates own profile" on doctor_profiles for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "patient permissions manage" on patient_doctor_permissions for all using(patient_id in(select id from patient_profiles where user_id=auth.uid())) with check(patient_id in(select id from patient_profiles where user_id=auth.uid()));
create policy "doctor sees permissions" on patient_doctor_permissions for select using(doctor_id in(select id from doctor_profiles where user_id=auth.uid()));
create policy "patient documents" on medical_documents for all using(patient_id in(select id from patient_profiles where user_id=auth.uid())) with check(patient_id in(select id from patient_profiles where user_id=auth.uid()));
create policy "doctor reads authorized documents" on medical_documents for select using(public.has_patient_access(patient_id));
create policy "patient consultations read" on consultations for select using(patient_id in(select id from patient_profiles where user_id=auth.uid()));
create policy "doctor consultations read" on consultations for select using(doctor_id in(select id from doctor_profiles where user_id=auth.uid()));
create policy "doctor consultations insert" on consultations for insert with check(doctor_id in(select id from doctor_profiles where user_id=auth.uid() and verification_status='verified') and public.has_patient_access(patient_id));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('medical-documents','medical-documents',false,10485760,array['application/pdf','image/jpeg','image/png']) on conflict(id) do nothing;
create policy "patient uploads private medical files" on storage.objects for insert to authenticated with check(bucket_id='medical-documents' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "patient reads own medical files" on storage.objects for select to authenticated using(bucket_id='medical-documents' and (storage.foldername(name))[1]=auth.uid()::text);
